import itertools,numpy as np
coords=[(0,0),(0,2),(1,1),(1,3),(2,1)] # r5c4,c6,r6c5,c7,r7c5
B={(0,2),(1,0),(1,1),(2,2)}
def norm(ps):
 mr=min(r for r,c in ps); mc=min(c for r,c in ps)
 return {(r-mr,c-mc) for r,c in ps}
def trans(ps):
 out=[]
 for f in [False,True]:
  q={(r,(-c if f else c)) for r,c in ps}
  for k in range(4):
   out.append((f,k,norm(q)))
   q={(c,-r) for r,c in q}
 return out
for subset in itertools.combinations(coords,4):
 for f,k,p in trans(subset):
  if p==norm(B): print('found',subset,f,k)
